<template x-if="modal==='api'"><div class="form-stack">
    <p class="muted">Token tenant untuk AI WhatsApp, billing, dan aplikasi teknisi. Token lengkap hanya ditampilkan sekali.</p>
    <label>API Base URL<div class="copy-field"><code x-text="apiInfo.base_url"></code><button class="icon-button" @click="copy(apiInfo.base_url)" aria-label="Salin API Base URL"><i data-lucide="copy"></i></button></div></label>
    <a class="text-button" :href="apiInfo.documentation_url" target="_blank" rel="noopener">Dokumentasi endpoint API</a>
    <form class="form-grid" @submit.prevent="createApiToken()"><label>Nama integrasi<input x-model="tokenForm.name" required maxlength="100" placeholder="Bot AI WhatsApp"></label><label>Masa berlaku (hari)<input type="number" x-model.number="tokenForm.days" min="1" max="365" required></label><label>Izin token<select x-model="tokenForm.scope"><option value="read">Read-only</option><option value="write">Read dan Write</option></select></label><button class="btn primary" :disabled="busy">Buat token API</button></form>
    <div class="notice" x-show="newToken"><div><strong>Salin token sekarang</strong><code class="token-value" x-text="newToken"></code><button class="text-button" @click="copy(newToken)">Salin token</button></div></div>
    <div class="table-scroll"><table><thead><tr><th>Nama</th><th>Izin</th><th>Kedaluwarsa</th><th>Terakhir dipakai</th><th>Aksi</th></tr></thead><tbody><template x-for="token in apiInfo.tokens" :key="token.id"><tr><td x-text="token.name"></td><td x-text="token.abilities.join(', ')"></td><td x-text="token.expires_at?dateTime(token.expires_at):'Tanpa batas'"></td><td x-text="token.last_used_at?dateTime(token.last_used_at):'Belum dipakai'"></td><td><button class="text-button red-text" @click="revokeApiToken(token)">Cabut token</button></td></tr></template></tbody></table></div>
</div></template>
